### 2️⃣ **Bedrock 호출 최적화** (근본 해결)
```javascript
// index.js 수정 제안
const invokeClaudeWithBackoff = async (prompt, maxRetries = 3) => {
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await invokeClaude(prompt);
    } catch (error) {
      if (error.name === 'ThrottlingException') {
        // 지수 백오프: 1초, 2초, 4초
        await new Promise(r => setTimeout(r, Math.pow(2, i) * 1000));
        continue;
      }
      throw error;
    }
  }
};

// 병렬 호출 제한 (동시 최대 5개)
