  for (let i = 0; i < count; i += batchSize) {
    const batch = count - i > batchSize ? batchSize : count - i;
    await fetch('/api/synthetic-data', {
      method: 'POST',
      body: JSON.stringify({ count: batch })
    });
    // 배치 사이에 1초 대기
    await new Promise(r => setTimeout(r, 1000));
  }
}
```

